<div class="admin-dashboard"><header class="dashboard-heading admin-dashboard-hero"><div><h1>Admin dashboard</h1><p class="muted">Authorized marketplace operations and review queues.</p></div><?php if(H::canAdmin('payments.view')):?><a class="btn" href="/admin/payment-logs">Payment, Stripe &amp; webhook report</a><?php endif;?></header>
<?php $visibleAttention=array_filter($attention,fn($item)=>H::canAdmin($item[0]));if($visibleAttention):?><section class="card attention-panel admin-dashboard-section"><h2>Attention Required</h2><div class="dashboard-grid"><?php foreach($visibleAttention as [,$label,$count,$url]):?><a class="card" href="<?=$url?>"><strong><?=number_format((int)$count)?></strong><span><?=H::e($label)?></span></a><?php endforeach;?></div></section><?php endif;?>
<?php if(H::canAdmin('users.view')||H::canAdmin('designers.view')||H::canAdmin('products.view')||H::canAdmin('orders.view')||H::canAdmin('payments.view')):?><section class="admin-dashboard-section admin-stats-section"><h2>Marketplace Statistics</h2><div class="dashboard-grid"><?php if(H::canAdmin('users.view')):foreach([['Total users',$s['total_users']],['Buyers',$s['total_buyers']]] as [$label,$value]):?><div class="card"><strong><?=H::e((string)$value)?></strong><span><?=H::e($label)?></span></div><?php endforeach;endif;?><?php if(H::canAdmin('designers.view')):?><div class="card"><strong><?=(int)$s['approved_designers']?></strong><span>Approved sellers</span></div><?php endif;?><?php if(H::canAdmin('products.view')):foreach([['Active products',$s['active_products']],['Draft products',$s['draft_products']]] as [$label,$value]):?><div class="card"><strong><?=(int)$value?></strong><span><?=H::e($label)?></span></div><?php endforeach;endif;?><?php if(H::canAdmin('payments.view')):foreach([['Live gross sales',H::money($s['live_gross_sales'])],['Marketplace commission',H::money($s['creative_moth_commission'])],['Seller payouts',H::money($s['seller_payouts'])]] as [$label,$value]):?><div class="card"><strong><?=H::e((string)$value)?></strong><span><?=H::e($label)?></span></div><?php endforeach;endif;?></div></section><?php endif;?>
<?php if(H::canAdmin('waitlist.view')):?><section class="admin-dashboard-section"><h2>Waitlist</h2><div class="dashboard-grid"><?php foreach([['Total',$waitlist['total']],['Recent / new',$waitlist['recent']],['Awaiting invitation',$waitlist['awaiting_invitation']]] as [$label,$value]):?><div class="card"><strong><?=number_format((int)$value)?></strong><span><?=H::e($label)?></span></div><?php endforeach;?></div><a href="/admin/waitlist">Manage waitlist</a></section><?php endif;?>
<div class="dashboard-columns admin-dashboard-section"><?php if(H::canAdmin('users.manage')):?><section class="card"><h2>Recent Activity</h2><ul><?php foreach($recentActivity as $activity):?><li><?=H::e(ucwords(str_replace('_',' ',$activity['action'])))?> · <?=H::e($activity['entity_type'])?> #<?=(int)$activity['entity_id']?></li><?php endforeach;?></ul></section><?php endif;?><section class="card"><h2>Recent Admin Notifications <span class="badge"><?=$unreadCount?></span></h2><?php foreach($notifications as $notification):?><p><strong><?=H::e($notification['title'])?></strong><br><?=H::e($notification['message'])?></p><?php endforeach;?><a href="/notifications">All notifications</a></section></div>
<section class="admin-dashboard-section admin-quick-section"><h2>Quick Actions</h2><div class="quick-actions"><?php foreach($quick as [$permission,$url,$label]):if(H::canAdmin($permission)):?><a class="btn" href="<?=$url?>"><?=H::e($label)?></a><?php endif;endforeach;?><a class="btn alt" href="/account">Account</a><a class="btn alt" href="/notifications">Notifications</a></div></section></div>
